    @InjectRepository(RiskAlert)
    private readonly riskAlertRepository: Repository<RiskAlert>,
    private readonly securityEventsService: SecurityEventsService,
  ) {}

  private get mediumThreshold(): number {
    return Number(process.env.RISK_AUTH_MEDIUM_THRESHOLD ?? 50);
  }

  private get highThreshold(): number {
    return Number(process.env.RISK_AUTH_HIGH_THRESHOLD ?? 80);
  }

  async use(req: RiskAuthRequest, _res: Response, next: NextFunction) {
    const assessment = await this.buildAssessment(req);
    req.risk_auth = assessment;
    if (assessment.reason_codes.length > 0) {
      await this.securityEventsService.logEvent({
        user_id: assessment.user_id,
        event_type: 'DEVICE_ANOMALY',
        metadata: {
          risk_score: assessment.risk_score,
          risk_level: assessment.level,
          reason_codes: assessment.reason_codes,
          country: assessment.context.country,
          device_fingerprint: assessment.context.device_fingerprint,
        },
        ip_address: assessment.context.ip,
        device_id: assessment.context.device_id,
      });
    }
    if (assessment.level === 'HIGH' && assessment.user_id) {
      await this.riskAlertRepository.save({
        type: 'ADAPTIVE_AUTH_HIGH_RISK',
        severity: 'HIGH',
        user_id: assessment.user_id,
        transaction_id: null,
        description: `High-risk adaptive auth event: ${assessment.reason_codes.join(', ')}`,
        risk_score: assessment.risk_score,
        status: 'OPEN',
      });
    }
    next();
  }

  private async buildAssessment(
    req: RiskAuthRequest,
  ): Promise<RiskAuthAssessment> {
    const userId = await this.resolveTargetUserId(req);
    const context = this.extractContext(req);
    if (!userId) {
      return {
        user_id: null,
        risk_score: 0,
        level: 'LOW',
        reason_codes: [],
        context,
      };
    }

    const lastLoginAudit = await this.auditRepository.findOne({
      where: { user_id: userId, action: 'LOGIN_SUCCESS' },
      order: { created_at: 'DESC' },
    });
    const previous = this.parsePreviousContext(lastLoginAudit?.metadata);

    let score = 0;
    const reasons: string[] = [];

    if (previous.ip && previous.ip !== context.ip) {
      score += 30;
      reasons.push('IP_CHANGED');
    }
    if (
      previous.country &&
      context.country &&
      previous.country.toUpperCase() !== context.country.toUpperCase()
    ) {
      score += 35;
      reasons.push('GEO_ANOMALY_COUNTRY_CHANGED');
    }
    if (
      previous.device_fingerprint &&
      previous.device_fingerprint !== context.device_fingerprint
    ) {
      score += 40;
      reasons.push('DEVICE_FINGERPRINT_MISMATCH');
    }

    const level: RiskAuthLevel =
      score >= this.highThreshold
        ? 'HIGH'
        : score >= this.mediumThreshold
          ? 'MEDIUM'
          : 'LOW';

    return {
      user_id: userId,
      risk_score: score,
      level,
      reason_codes: reasons,
      context,
    };
  }

  private async resolveTargetUserId(
    req: RiskAuthRequest,
  ): Promise<string | null> {
    const jwtUserId = (req as Request & { user?: { userId?: string } }).user
      ?.userId;
    if (jwtUserId) return jwtUserId;

    const phone = this.getString(req.body?.phone_number);
    if (!phone) return null;
    const accountType = this.getString(req.body?.account_type) ?? 'CONSUMER';
    const user = await this.userRepository.findOne({
      where: { phone_number: phone, account_type: accountType as any },
      select: ['id'],
    });
    return user?.id ?? null;
  }

  private extractContext(req: Request): RiskAuthAssessment['context'] {
    const ip =
      (req.ip || '').trim() ||
      ((req.connection as { remoteAddress?: string } | undefined)
        ?.remoteAddress ??
        '') ||
      '0.0.0.0';
    const country =
      this.getString(req.headers['cf-ipcountry']) ||
      this.getString(req.headers['x-country-code']) ||
      this.getString(req.headers['x-geo-country']) ||
      null;
    const deviceId = this.getString(req.headers['x-device-id']) ?? null;
    const userAgent = this.getString(req.headers['user-agent']) ?? null;
    const explicitFingerprint = this.getString(
      req.headers['x-device-fingerprint'],
    );
    const fingerprintSource =
      explicitFingerprint || `${deviceId || ''}|${userAgent || ''}`;
    const deviceFingerprint = createHash('sha256')
      .update(fingerprintSource)
      .digest('hex');
    return {
      ip,
      country,
      device_id: deviceId,
      device_fingerprint: deviceFingerprint,
      user_agent: userAgent,
    };
  }

  private parsePreviousContext(
    metadata: Record<string, unknown> | undefined | null,
  ): { ip?: string; country?: string; device_fingerprint?: string } {
    if (!metadata || typeof metadata !== 'object') return {};
    return {
      ip: this.getString(metadata.ip),
      country: this.getString(metadata.country),
      device_fingerprint: this.getString(metadata.device_fingerprint),
    };
  }

  private getString(value: unknown): string | undefined {
    return typeof value === 'string' && value.trim() ? value.trim() : undefined;
  }
}

/**
 * Phone number normalization to E.164.
 * Used for identity_phone_numbers and consistent lookups across the system.
 *
 * Bare national digits (and leading 0) still default to Morocco (+212) — correct
 * for local hosts. Clients that send an explicit `+` prefix are passed through
 * as international E.164 (tourists).
 */

import { BadRequestException } from '@nestjs/common';

/** E.164: +[country][subscriber] e.g. +212612345678 */
const E164_REGEX = /^\+[1-9]\d{1,14}$/;

/**
 * Default country code when none provided (Morocco).
 */
export const DEFAULT_COUNTRY_CODE = '212';

/**
 * Morocco: many users enter +21206… (national trunk 0 after country code).
 * E.164 is +2126… — strip the extra 0 after 212.
 */
function canonicalizeMoroccoTrunkZero(digits: string): string {
  if (digits.startsWith('2120') && digits.length >= 12) {
    const subscriber = digits.slice(4, 13);
    if (subscriber.length === 9) {
      return `212${subscriber}`;
    }
  }
  return digits;
}

/**
 * Normalize phone number to E.164 format.
 * Accepts: 0612345677, 612345677, 212612345677, +212612345677, +2120612345678, +12025551234
 * Returns e.g. +212612345678 or +12025551234
 * @throws Error if input cannot be parsed
 */
export function normalizePhoneNumber(raw: string): string {
  const s = String(raw ?? '').trim();
  const digits = canonicalizeMoroccoTrunkZero(s.replace(/\D/g, ''));

  // Pass through valid E.164 when explicitly prefixed with +
  if (s.startsWith('+') && /^[1-9]\d{9,14}$/.test(digits)) {
    const candidate = `+${digits}`;
    if (E164_REGEX.test(candidate)) return candidate;
  }
  if (!digits || digits.length < 9) {
    throw new Error('Invalid phone number: too few digits');
  }
  let normalized: string;
  if (digits.startsWith('212') && digits.length >= 12) {
    normalized = `+${digits.slice(0, 12)}`;
  } else if (digits.startsWith('0') && digits.length >= 10) {
    normalized = `+${DEFAULT_COUNTRY_CODE}${digits.slice(1).slice(0, 9)}`;
  } else if (digits.startsWith('212') && digits.length >= 9) {
    normalized = `+212${digits.slice(3).slice(0, 9)}`;
  } else if (digits.length >= 9 && digits.startsWith('6')) {
    normalized = `+${DEFAULT_COUNTRY_CODE}${digits.slice(0, 9)}`;
  } else {
    normalized = `+${DEFAULT_COUNTRY_CODE}${digits.slice(-9)}`;
  }
  if (!E164_REGEX.test(normalized) || normalized.length < 12) {
    throw new Error(`Invalid phone number: cannot normalize "${raw}"`);
  }
  return normalized;
}

/**
 * Try to normalize; returns null on failure.
 */
export function tryNormalizePhoneNumber(raw: string): string | null {
  try {
    return normalizePhoneNumber(raw);
  } catch {
    return null;
  }
}

export interface ValidatePhoneResult {
  valid: boolean;
  error?: string;
  normalized?: string;
}

/**
 * Validate and optionally normalize. Use for input validation.
 */
export function validatePhoneNumber(raw: string): ValidatePhoneResult {
  const s = String(raw ?? '').trim();
  if (!s) return { valid: false, error: 'Phone number is required' };
  const digits = s.replace(/\D/g, '');
  if (digits.length < 9) return { valid: false, error: 'Phone number has too few digits' };
  if (digits.length > 15) return { valid: false, error: 'Phone number has too many digits' };
  if (/^0+$/.test(digits) || /^0\d{0,5}$/.test(digits)) {
    return { valid: false, error: 'Phone number is invalid or ambiguous' };
  }
  try {
    const normalized = normalizePhoneNumber(s);
    return { valid: true, normalized };
  } catch (e) {
    return { valid: false, error: (e as Error).message ?? 'Invalid phone number' };
  }
}

/**
 * Normalize or throw BadRequestException. Use at API/service entry points.
 */
export function normalizePhoneOrThrow(raw: string): string {
  const result = validatePhoneNumber(raw);
  if (!result.valid) {
    throw new BadRequestException(result.error ?? 'Invalid phone number');
  }
  return result.normalized!;
}

function looksLikeMorocco(raw: string, digits: string, normalized: string | null): boolean {
  if (normalized?.startsWith('+212')) return true;
  if (digits.startsWith('212')) return true;
  const trimmed = raw.trim();
  // Explicit non-MA international prefix — do not invent +212 variants
  if (trimmed.startsWith('+') && !digits.startsWith('212')) return false;
  if (trimmed.startsWith('00') && !digits.startsWith('00212') && !digits.startsWith('212')) {
    return false;
  }
  // Bare national / leading 0 → treated as MA by normalizePhoneNumber
  return true;
}

/**
 * All plausible stored forms for the same number.
 * Moroccan numbers also match legacy local/0/212 variants.
 * Non-MA E.164 only matches the normalized form (and digit-only), avoiding
 * false +212 merges from last-9 digits.
 */
export function phoneLookupCandidates(raw: string): string[] {
  const trimmed = String(raw ?? '').trim();
  if (!trimmed) return [];

  const digits = trimmed.replace(/\D/g, '');
  const normalized = tryNormalizePhoneNumber(trimmed);

  const out = new Set<string>();
  if (trimmed) out.add(trimmed);
  if (digits) out.add(digits);
  if (normalized) {
    out.add(normalized);
    out.add(normalized.slice(1));
  }

  if (looksLikeMorocco(trimmed, digits, normalized)) {
    const local9 = digits.length >= 9 ? digits.slice(-9) : '';
    if (local9) {
      out.add(local9);
      out.add(`0${local9}`);
      out.add(`212${local9}`);
      out.add(`+212${local9}`);
    }
  }

  return [...out];
}

/**
 * Nexa deployment stage contract (PROD-OPS-002).
 * Keep Identity + Stays copies aligned.
 */

export type NexaStage =
  | 'development'
  | 'dogfood'
  | 'staging'
  | 'production';

export function resolveNexaStage(
  env: NodeJS.ProcessEnv = process.env,
): NexaStage {
  const explicit = (env.NEXA_ENV || env.APP_ENV || '').trim().toLowerCase();
  if (
    explicit === 'production' ||
    explicit === 'staging' ||
    explicit === 'dogfood' ||
    explicit === 'development'
  ) {
    return explicit;
  }
  // Legacy: NODE_ENV=production without NEXA_ENV ⇒ treat as real production (fail-closed policies apply).
  if (env.NODE_ENV === 'production') return 'production';
  return 'development';
}

export function parseCorsOriginsList(
  env: NodeJS.ProcessEnv = process.env,
): string[] {
  return (env.CORS_ORIGINS || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

export const DEV_DEFAULT_CORS_ORIGINS = [
  'http://localhost:3000',
  'http://127.0.0.1:3000',
  'http://localhost:3003',
  'http://127.0.0.1:3003',
  'http://localhost:3001',
  'http://127.0.0.1:3001',
  'http://localhost:3005',
  'http://127.0.0.1:3005',
];

/**
 * Explicit origin allowlist. Never returns `true` (reflect-any).
 * dogfood/staging/production require CORS_ORIGINS.
 */
/**
 * Credentials are always enabled on Identity. Reject wildcard / null origins
 * whenever CORS_ORIGINS is explicitly configured (any stage).
 */
export function assertNoCredentialedWildcardCors(
  origins: string[],
): void {
  for (const origin of origins) {
    const o = origin.trim();
    if (o === '*' || o.toLowerCase() === 'null') {
      throw new Error(
        'CORS_ORIGINS must not contain "*" or "null" when credentials are enabled.',
      );
    }
  }
}

export function resolveCorsAllowlist(
  env: NodeJS.ProcessEnv = process.env,
): string[] {
  const stage = resolveNexaStage(env);
  const configured = parseCorsOriginsList(env);

  if (stage === 'production' || stage === 'staging' || stage === 'dogfood') {
    if (configured.length === 0) {
      throw new Error(
        `CORS_ORIGINS must be set for ${stage} (comma-separated trusted origins). Arbitrary Origin reflection is disabled.`,
      );
    }
    assertNoCredentialedWildcardCors(configured);
    return configured;
  }

  const list =
    configured.length > 0 ? configured : [...DEV_DEFAULT_CORS_ORIGINS];
  assertNoCredentialedWildcardCors(configured);
  return list;
}

import { createCipheriv, createDecipheriv, randomBytes } from 'crypto';
import type { ValueTransformer } from 'typeorm';

const PREFIX = 'enc:v1';

function key(): Buffer {
  const encoded = process.env.PII_ENCRYPTION_KEY?.trim();
  if (!encoded) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('PII_ENCRYPTION_KEY is required in production.');
    }
    return Buffer.alloc(32, 0);
  }
  const decoded = Buffer.from(encoded, 'base64');
  if (decoded.length !== 32) {
    throw new Error('PII_ENCRYPTION_KEY must be a base64-encoded 32-byte key.');
  }
  return decoded;
}

export function encryptPii(value: string): string {
  if (!value || value.startsWith(`${PREFIX}:`)) return value;
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key(), iv);
  const ciphertext = Buffer.concat([cipher.update(value, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return [PREFIX, iv.toString('base64url'), tag.toString('base64url'), ciphertext.toString('base64url')].join(':');
}

export function decryptPii(value: string): string {
  if (!value || !value.startsWith(`${PREFIX}:`)) return value;
  const [, , ivText, tagText, cipherText] = value.split(':');
  const decipher = createDecipheriv('aes-256-gcm', key(), Buffer.from(ivText, 'base64url'));
  decipher.setAuthTag(Buffer.from(tagText, 'base64url'));
  return Buffer.concat([
    decipher.update(Buffer.from(cipherText, 'base64url')),
    decipher.final(),
  ]).toString('utf8');
}

export const piiTransformer: ValueTransformer = {
  to: (value: string | null | undefined) =>
    value == null ? value : encryptPii(value),
  from: (value: string | null | undefined) =>
    value == null ? value : decryptPii(value),
};

/**
 * Dogfood / production fail-closed env policy (Phase 1 + Phase 2A gates).
 * Extracted for unit tests — call from bootstrap.
 *
 * Demo OTP, Sumsub sandbox, and EMI mock remain available for development/dogfood.
 * Real production (NEXA_ENV=production) must never silently use those modes.
 */

import { resolveNexaStage } from './cors-origins';

const KNOWN_INSECURE_VALUES = new Set([
  'dev-internal-key',
  'nexa_identity_dev',
  'nexa_stays_dev',
  'dev-only-secret-not-for-production',
  'dev-otp-pepper-not-for-production',
  'dev-refresh-pepper-not-for-production',
  'CHANGE_ME',
  'REPLACE',
  'REPLACE_STRONG_PASSWORD',
  'dev',
]);

export function assertDemoOtpForbiddenInProduction(
  env: NodeJS.ProcessEnv = process.env,
): void {
  const demoCode = (env.DEMO_OTP_CODE ?? '').trim();
  if (!demoCode) return;
  if (!/^\d{6}$/.test(demoCode)) {
    throw new Error('DEMO_OTP_CODE must contain exactly 6 digits.');
  }
  if (env.NODE_ENV === 'production' && env.NEXA_ENV !== 'dogfood') {
    throw new Error(
      'DEMO_OTP_CODE is allowed only when NEXA_ENV=dogfood; it is forbidden in staging and production.',
    );
  }
}

function isLoopbackHostname(hostname: string): boolean {
  const h = hostname.trim().toLowerCase().replace(/^\[|\]$/g, '');
  return h === 'localhost' || h === '127.0.0.1' || h === '::1';
}

export function urlLooksLikeLoopback(raw: string): boolean {
  const value = raw.trim();
  if (!value) return false;
  try {
    return isLoopbackHostname(new URL(value).hostname);
  } catch {
    return /(?:^|[/:])(?:localhost|127\.0\.0\.1|::1)(?:$|[/:?#])/i.test(value);
  }
}

/**
 * When NODE_ENV=production (dogfood VPS contract included), reject known
 * development/placeholder secret values that were explicitly configured.
 * Missing required secrets are enforced elsewhere.
 */
export function assertNoInsecureProductionSecrets(
  env: NodeJS.ProcessEnv = process.env,
): void {
  if (env.NODE_ENV !== 'production') return;

  const checks: Array<[string, string | undefined]> = [
    ['INTERNAL_SERVICE_KEY', env.INTERNAL_SERVICE_KEY],
    ['DB_PASSWORD', env.DB_PASSWORD],
    ['JWT_SECRET', env.JWT_SECRET],
  ];

  for (const [name, raw] of checks) {
    const value = (raw ?? '').trim();
    if (!value) continue;
    if (
      KNOWN_INSECURE_VALUES.has(value) ||
      /^nexa_(identity|stays)_dev$/i.test(value)
    ) {
      throw new Error(
        `${name} uses a known development/default value which is forbidden when NODE_ENV=production.`,
      );
    }
  }
}

/**
 * Service URLs must not silently point at loopback on production Node
 * (includes dogfood VPS with NODE_ENV=production).
 */
export function assertNoLoopbackProductionServiceUrls(
  env: NodeJS.ProcessEnv = process.env,
): void {
  if (env.NODE_ENV !== 'production') return;

  const keys = [
    'JWT_ISSUER',
    'IDENTITY_BASE_URL',
    'IDENTITY_JWKS_URL',
    'STAYS_API_BASE_URL',
  ] as const;

  for (const key of keys) {
    const raw = (env[key] ?? '').trim();
    if (!raw) continue;
    if (urlLooksLikeLoopback(raw)) {
      throw new Error(
        `${key} must not use a loopback host (localhost / 127.0.0.1 / ::1) when NODE_ENV=production.`,
      );
    }
  }
}

export type SumsubMode = 'sandbox' | 'live';

/** Explicit Sumsub environment — sandbox for dogfood/dev; live required for real production. */
export function getSumsubMode(env: NodeJS.ProcessEnv = process.env): SumsubMode {
  const raw = (env.SUMSUB_MODE ?? '').trim().toLowerCase();
  if (raw === 'live' || raw === 'sandbox') return raw;
  const stage = resolveNexaStage(env);
  return stage === 'production' ? 'live' : 'sandbox';
}

/**
 * Real production must not run Sumsub sandbox mode.
 * Dogfood/dev may set SUMSUB_MODE=sandbox explicitly.
 */
export function assertSumsubModePolicy(
  env: NodeJS.ProcessEnv = process.env,
): void {
  const stage = resolveNexaStage(env);
  const explicit = (env.SUMSUB_MODE ?? '').trim().toLowerCase();
  if (stage !== 'production') return;

  if (explicit === 'sandbox') {
    throw new Error(
      'SUMSUB_MODE=sandbox is not allowed when NEXA_ENV=production. Use SUMSUB_MODE=live with production Sumsub credentials.',
    );
  }
  if (explicit && explicit !== 'live') {
    throw new Error(
      `Unsupported SUMSUB_MODE="${explicit}". Allowed: sandbox | live.`,
    );
  }
  if (!explicit) {
    throw new Error(
      'NEXA_ENV=production requires SUMSUB_MODE=live explicitly set (no silent sandbox default).',
    );
  }
}

/**
 * Wallet EMI mock is for local/dogfood only. Real production must not use mock EMI.
 * Set EMI_PROVIDER_TYPE=disabled when wallet top-up is not offered in production yet.
 * Does not delete mock provider code — only rejects the combination at boot.
 */
export function assertEmiProviderPolicy(
  env: NodeJS.ProcessEnv = process.env,
): void {
  const stage = resolveNexaStage(env);
  if (stage !== 'production') return;

  const explicit = (env.EMI_PROVIDER_TYPE ?? '').trim().toLowerCase();
  if (!explicit) {
    throw new Error(
      'NEXA_ENV=production requires EMI_PROVIDER_TYPE explicitly set ' +
        '(real provider name, or "disabled" if wallet top-up is not offered). ' +
        'Silent default mock is forbidden.',
    );
  }
  if (explicit === 'mock') {
    throw new Error(
      'EMI_PROVIDER_TYPE=mock is not allowed when NEXA_ENV=production. ' +
        'Use a real EMI provider, EMI_PROVIDER_TYPE=disabled, or NEXA_ENV=dogfood for mock top-up.',
    );
  }
}

/** Bundle used at Identity boot when NODE_ENV=production. */
export function assertIdentityProductionEnvPolicy(
  env: NodeJS.ProcessEnv = process.env,
): void {
  assertDemoOtpForbiddenInProduction(env);
  assertSumsubModePolicy(env);
  assertEmiProviderPolicy(env);
  if (env.NODE_ENV !== 'production') return;
  assertNoInsecureProductionSecrets(env);
  assertNoLoopbackProductionServiceUrls(env);
  void resolveNexaStage(env);
}

/**
 * Resolve secrets from environment. Never hardcode production credentials.
 * Dev-only fallbacks are allowed outside production so local docker-compose works.
 */

export function isProductionRuntime(): boolean {
  return process.env.NODE_ENV === 'production';
}

/** Required in production; optional dev fallback otherwise. */
export function requireSecret(
  name: string,
  options?: { devFallback?: string },
): string {
  const value = (process.env[name] ?? '').trim();
  if (value) return value;
  if (isProductionRuntime()) {
    throw new Error(`${name} is required in production and must be set via environment variables.`);
  }
  if (options?.devFallback !== undefined) return options.devFallback;
  throw new Error(`${name} is not set.`);
}

/** Internal service auth key shared between platform services. */
export function getInternalServiceKey(): string {
  return requireSecret('INTERNAL_SERVICE_KEY', {
    devFallback: 'dev-internal-key',
  });
}

import type { NestExpressApplication } from '@nestjs/platform-express';
import type { Request, Response, NextFunction } from 'express';
import helmet from 'helmet';

/**
 * Production-safe HTTP surface: trust proxy, HSTS, optional HTTPS redirect.
 * TLS termination is expected at the load balancer; apps honor X-Forwarded-Proto.
 */
export function applySecureHttp(app: NestExpressApplication): void {
  const isProd = process.env.NODE_ENV === 'production';
  const trustProxy =
    process.env.TRUST_PROXY === 'true' ||
    process.env.TRUST_PROXY === '1' ||
    isProd;

  if (trustProxy) {
    const hops = parseInt(process.env.TRUST_PROXY_HOPS || '1', 10);
    app.set('trust proxy', Number.isFinite(hops) && hops > 0 ? hops : 1);
  }

  app.use(
    helmet({
      contentSecurityPolicy: isProd,
      crossOriginEmbedderPolicy: false,
      crossOriginResourcePolicy: { policy: 'cross-origin' },
      hsts: isProd
        ? { maxAge: 31536000, includeSubDomains: true, preload: true }
        : false,
      referrerPolicy: { policy: 'no-referrer' },
    }),
  );
  app.disable('x-powered-by');

  const enforceHttps =
    isProd && process.env.ENFORCE_HTTPS !== 'false';
  if (enforceHttps) {
    app.use((req: Request, res: Response, next: NextFunction) => {
      const proto = String(req.headers['x-forwarded-proto'] || '')
        .split(',')[0]
        .trim()
        .toLowerCase();
      if (proto === 'http') {
        const host = req.headers.host || 'localhost';
        res.redirect(301, `https://${host}${req.originalUrl || req.url}`);
        return;
      }
      next();
    });
  }
}

import { safeLogger } from '../logging/safe-logger';

/**
 * In-process detector for bursty auth failures / rate-limit hits per IP.
 * Emits structured security logs when thresholds are crossed.
 */
const WINDOW_MS = 60_000;
const AUTH_FAIL_THRESHOLD = parseInt(
  process.env.SECURITY_AUTH_FAIL_BURST || '20',
  10,
);
const RATE_LIMIT_THRESHOLD = parseInt(
  process.env.SECURITY_RATE_LIMIT_BURST || '30',
  10,
);

type Bucket = { count: number; resetAt: number };

const authFails = new Map<string, Bucket>();
const rateLimits = new Map<string, Bucket>();

function bump(map: Map<string, Bucket>, key: string): number {
  const now = Date.now();
  const cur = map.get(key);
  if (!cur || now >= cur.resetAt) {
    map.set(key, { count: 1, resetAt: now + WINDOW_MS });
    return 1;
  }
  cur.count += 1;
  return cur.count;
}

function clientIp(req: {
  ip?: string;
  headers?: Record<string, string | string[] | undefined>;
  socket?: { remoteAddress?: string };
}): string {
  const xf = req.headers?.['x-forwarded-for'];
  const fromHeader = Array.isArray(xf)
    ? xf[0]
    : typeof xf === 'string'
      ? xf.split(',')[0].trim()
      : '';
  return (
    fromHeader ||
    req.ip ||
    req.socket?.remoteAddress ||
    '0.0.0.0'
  );
}

export function noteAuthFailure(
  req: {
    ip?: string;
    headers?: Record<string, string | string[] | undefined>;
    socket?: { remoteAddress?: string };
    method?: string;
    url?: string;
    path?: string;
  },
  meta?: Record<string, unknown>,
): void {
  const ip = clientIp(req);
  const n = bump(authFails, ip);
  safeLogger.info('security.auth_failure', {
    ip,
    path: req.path || req.url,
    method: req.method,
    burstCount: n,
    ...meta,
  });
  if (n >= AUTH_FAIL_THRESHOLD) {
    safeLogger.info('security.unusual_traffic', {
      kind: 'AUTH_FAILURE_BURST',
      ip,
      count: n,
      windowMs: WINDOW_MS,
    });
  }
}

export function noteRateLimited(
  req: {
    ip?: string;
    headers?: Record<string, string | string[] | undefined>;
    socket?: { remoteAddress?: string };
    method?: string;
    url?: string;
    path?: string;
  },
): void {
  const ip = clientIp(req);
  const n = bump(rateLimits, ip);
  safeLogger.info('security.rate_limited', {
    ip,
    path: req.path || req.url,
    method: req.method,
    burstCount: n,
  });
  if (n >= RATE_LIMIT_THRESHOLD) {
    safeLogger.info('security.unusual_traffic', {
      kind: 'RATE_LIMIT_BURST',
      ip,
      count: n,
      windowMs: WINDOW_MS,
    });
  }
}

export function noteApiError(
  req: {
    ip?: string;
    headers?: Record<string, string | string[] | undefined>;
    socket?: { remoteAddress?: string };
    method?: string;
    url?: string;
    path?: string;
    requestId?: string;
  },
  status: number,
  message: string,
): void {
  const payload = {
    ip: clientIp(req),
    path: req.path || req.url,
    method: req.method,
    status,
    message: message.slice(0, 200),
    requestId: req.requestId,
  };
  if (status >= 500) {
    safeLogger.error('security.api_error', undefined, payload);
  } else {
    safeLogger.info('security.api_error', payload);
  }

  if (status === 401 || status === 403) {
    noteAuthFailure(req, { status });
  }
  if (status === 429) {
    noteRateLimited(req);
  }
}

/**
 * PROD-SEC-002 — Identity upload storage fail-closed for real production.
 * Local KYC/profile disk writes are allowed in development/dogfood only.
 * Real production requires IDENTITY_DISABLE_LOCAL_UPLOADS=true (Sumsub / no local files).
 */
export type UploadStage = 'development' | 'dogfood' | 'staging' | 'production';

export function resolveUploadStage(
  env: NodeJS.ProcessEnv = process.env,
): UploadStage {
  const explicit = (env.NEXA_ENV || env.APP_ENV || '').trim().toLowerCase();
  if (
    explicit === 'production' ||
    explicit === 'staging' ||
    explicit === 'dogfood' ||
    explicit === 'development'
  ) {
    return explicit;
  }
  if (env.NODE_ENV === 'production') return 'production';
  return 'development';
}

export function isIdentityLocalUploadDisabled(
  env: NodeJS.ProcessEnv = process.env,
): boolean {
  return env.IDENTITY_DISABLE_LOCAL_UPLOADS === 'true';
}

/**
 * Real production must disable Identity local KYC/profile disk uploads.
 * Soft-launch dogfood may keep local uploads.
 */
export function assertProductionIdentityUploadConfigured(
  env: NodeJS.ProcessEnv = process.env,
): void {
  const stage = resolveUploadStage(env);
  if (stage !== 'production') return;

  if (env.MEDIA_ALLOW_LOCAL_STORAGE === 'true') {
    throw new Error(
      'MEDIA_ALLOW_LOCAL_STORAGE is not permitted when NEXA_ENV=production (PROD-SEC-002).',
    );
  }

  if (!isIdentityLocalUploadDisabled(env)) {
    throw new Error(
      'Production Identity requires IDENTITY_DISABLE_LOCAL_UPLOADS=true (Sumsub / no local KYC-profile disk uploads) (PROD-SEC-002).',
    );
  }
}

export function assertIdentityLocalUploadsAllowed(
  env: NodeJS.ProcessEnv = process.env,
): void {
  if (isIdentityLocalUploadDisabled(env)) {
    throw new Error(
      'Local Identity uploads are disabled (IDENTITY_DISABLE_LOCAL_UPLOADS=true). Use Sumsub or media-service for KYC/profile media.',
    );
  }
}

/**
 * Provider-synced KYC media (bytes fetched from Sumsub with HMAC auth) may be
 * written to disk even when client local uploads are disabled. Bytes never
 * originate from the browser.
 */
export function assertIdentityProviderMediaSyncAllowed(
  _env: NodeJS.ProcessEnv = process.env,
): void {
  // Intentionally permissive relative to IDENTITY_DISABLE_LOCAL_UPLOADS.
  // Fail closed only if storage root is explicitly forbidden via env later.
  void _env;
}

export function isSvgBuffer(buffer: Buffer): boolean {
  if (!buffer || buffer.length < 5) return false;
  const head = buffer
    .subarray(0, Math.min(256, buffer.length))
    .toString('utf8')
    .trimStart()
    .toLowerCase();
  return head.startsWith('<svg') || (head.startsWith('<?xml') && head.includes('<svg'));
}

