import { AuthzModule } from '../authz/authz.module';

@Module({
  imports: [
    TypeOrmModule.forFeature([
      User,
      OtpCode,
      OtpSession,
      OtpAttempt,
      PinAttempt,
      RefreshToken,
      TrustedDevice,
      AuditLog,
      RiskAlert,
      KycProfile,
    ]),
    PassportModule,
    JwtModule.registerAsync({
      inject: [JwtKeysService],
      useFactory: (keys: JwtKeysService) => ({
        privateKey: keys.privateKey,
        publicKey: keys.publicKey,
        signOptions: {
          algorithm: 'RS256',
          expiresIn: getJwtAccessExpiresIn(),
          keyid: keys.kid,
          issuer: getJwtIssuer(),
          audience: getJwtAudience(),
        } as any,
      }),
    }),
    UsersModule,
    AuditModule,
    SecurityEventsModule,
    AuthzModule,
  ],
  controllers: [AuthController],
  providers: [
    AuthService,
    JwtStrategy,
    OtpLockoutService,
    PinLockoutService,
    OtpSendRateLimitService,
    OtpVerifyRateLimitService,
    OtpSendRateLimitGuard,
    OtpVerifyRateLimitGuard,
  ],
  exports: [AuthService, AuthzModule],
})
export class AuthModule implements NestModule {
  configure(consumer: MiddlewareConsumer) {
    consumer
      .apply(RiskAuthMiddleware)
      .forRoutes(
        'auth/verify-pin',
        'auth/pin/verify',
        'pay/auth/verify-pin',
        'pay/auth/pin/verify',
      );
  }
}

