import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import type { Request, Response } from 'express';
import { map, type Observable } from 'rxjs';
import {
  isBrowserCookieRequest,
  refreshCookieName,
  setBrowserAuthCookies,
} from './browser-auth-cookies';

type TokenResponse = {
  access_token?: unknown;
  refresh_token?: unknown;
  [key: string]: unknown;
};

/**
 * Cookie transport (X-Auth-Transport: cookie):
 * - Set HttpOnly refresh cookie
 * - Never set ambient access cookie (ADR-005 / PROD-SEC-001)
 * - Strip refresh_token from JSON body (JS must not read it)
 * - Leave access_token in JSON for in-memory Bearer use
 */
@Injectable()
export class BrowserAuthInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<Request>();
    const response = context.switchToHttp().getResponse<Response>();
    if (!isBrowserCookieRequest(request)) return next.handle();

    return next.handle().pipe(
      map((value: unknown) => {
        if (!value || typeof value !== 'object') return value;
        const result = value as TokenResponse;
        if (typeof result.access_token !== 'string') return value;
        setBrowserAuthCookies(
          response,
          {
            access_token: result.access_token,
            refresh_token:
              typeof result.refresh_token === 'string'
                ? result.refresh_token
                : undefined,
          },
          refreshCookieName(request),
        );
        const { refresh_token: _refreshToken, ...safeResult } = result;
        return safeResult;
      }),
    );
  }
}

import { Injectable } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { JwtKeysService } from '../../jwks/jwt-keys.service';
import type { Request } from 'express';
import { extractBearerAccessToken } from '../security/bearer-access-token';
import { getJwtAudience, getJwtIssuer } from '../../../common/security/jwt-claims';

export interface JwtPayload {
  sub: string;
  phone_number?: string;
  role?: string;
  roles?: string[];
  email?: string;
  type?: string;
  account_type?: string;
  unified_identity_id?: string;
  session_id?: string;
  auth_method?: string;
  kyc_verified?: boolean;
  kyc_tier?: string;
  /** SEC-003 admin authz version */
  av?: number;
  iss?: string;
  aud?: string | string[];
}

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private readonly jwtKeys: JwtKeysService) {
    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        (request: Request) => extractBearerAccessToken(request),
      ]),
      ignoreExpiration: false,
      secretOrKey: jwtKeys.publicKey,
      algorithms: ['RS256'],
      issuer: getJwtIssuer(),
      audience: getJwtAudience(),
    });
  }

  async validate(payload: JwtPayload) {
    if (payload.type === 'otp_session' || payload.type === 'identity_session') {
      return {
        userId: payload.sub,
        type: payload.type,
        phone_number: payload.phone_number,
        unified_identity_id: payload.unified_identity_id,
      };
    }
    return {
      userId: payload.sub,
      account_type: payload.account_type ?? 'CONSUMER',
      unified_identity_id: payload.unified_identity_id,
      session_id: payload.session_id,
      auth_method: payload.auth_method,
      role: payload.role,
      roles: payload.roles,
      email: payload.email,
      phone_number: payload.phone_number,
      kyc_verified: payload.kyc_verified === true,
      kyc_tier: payload.kyc_tier,
      authz_version: payload.av,
      av: payload.av,
    };
  }
}

