import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import {
  cert,
  getApps,
  initializeApp,
  type App,
  type ServiceAccount,
} from 'firebase-admin/app';
import { getMessaging } from 'firebase-admin/messaging';
import { PushDeviceToken } from './entities/push-device-token.entity';
import { safeLogger } from '../../common/logging/safe-logger';

interface PushPayload {
  title: string;
  body: string;
  reference: string;
  amount: string;
  direction: string;
  event: string;
}

@Injectable()
export class NotificationsService {
  private firebaseApp: App | null = null;

  constructor(
    @InjectRepository(PushDeviceToken)
    private readonly pushTokenRepository: Repository<PushDeviceToken>,
  ) {
    this.initializeFirebaseAdmin();
  }

  private initializeFirebaseAdmin(): void {
    const existingApp = getApps()[0];
    if (existingApp) {
      this.firebaseApp = existingApp;
      return;
    }
    try {
      const serviceAccountJson = process.env.FCM_SERVICE_ACCOUNT_JSON;
      const serviceAccountPath = process.env.FCM_SERVICE_ACCOUNT_PATH;
      if (!serviceAccountJson && !serviceAccountPath) {
        safeLogger.info('FCM disabled: missing service account env');
        return;
      }
      let serviceAccount: ServiceAccount;
      if (serviceAccountJson) {
        serviceAccount = JSON.parse(serviceAccountJson) as ServiceAccount;
      } else {
        serviceAccount = require(serviceAccountPath!) as ServiceAccount;
      }
      this.firebaseApp = initializeApp({ credential: cert(serviceAccount) });
      safeLogger.info('FCM initialized');
    } catch (error) {
      safeLogger.error('FCM initialization failed', error);
    }
  }

  async registerPushToken(params: {
    userId: string;
    deviceId: string;
    token: string;
    platform?: string;
    notificationsEnabled?: boolean;
  }): Promise<void> {
    const deviceId = params.deviceId.trim().slice(0, 120);
    if (!deviceId || !params.token) return;
    const existing = await this.pushTokenRepository.findOne({
      where: { user_id: params.userId, device_id: deviceId },
    });
    const now = new Date();
    if (!existing) {
      await this.pushTokenRepository.save({
        user_id: params.userId,
        device_id: deviceId,
        token: params.token,
        platform: (params.platform || 'unknown').slice(0, 20),
        notifications_enabled: params.notificationsEnabled ?? true,
        active: true,
        last_seen_at: now,
      });
      return;
    }
    existing.token = params.token;
    existing.platform = (
      params.platform ||
      existing.platform ||
      'unknown'
    ).slice(0, 20);
    existing.notifications_enabled =
      params.notificationsEnabled ?? existing.notifications_enabled;
    existing.active = true;
    existing.last_seen_at = now;
    await this.pushTokenRepository.save(existing);
  }

  async deactivatePushToken(params: {
    userId: string;
    deviceId?: string | null;
    token?: string | null;
  }): Promise<void> {
    const qb = this.pushTokenRepository
      .createQueryBuilder()
      .update(PushDeviceToken)
      .set({ active: false });
    qb.where('user_id = :userId', { userId: params.userId });
    if (params.deviceId)
      qb.andWhere('device_id = :deviceId', { deviceId: params.deviceId });
    if (params.token) qb.andWhere('token = :token', { token: params.token });
    await qb.execute();
  }

  async updateNotificationPreference(params: {
    userId: string;
    enabled: boolean;
    deviceId?: string | null;
  }): Promise<void> {
    const qb = this.pushTokenRepository
      .createQueryBuilder()
      .update(PushDeviceToken)
      .set({ notifications_enabled: params.enabled });
    qb.where('user_id = :userId', { userId: params.userId });
    if (params.deviceId)
      qb.andWhere('device_id = :deviceId', { deviceId: params.deviceId });
    await qb.execute();
  }

  async sendToUser(userId: string, payload: PushPayload): Promise<void> {
    if (!this.firebaseApp) return;
    const rows = await this.pushTokenRepository.find({
      where: { user_id: userId, active: true, notifications_enabled: true },
    });
    const tokens = rows.map((r) => r.token).filter(Boolean);
    if (!tokens.length) return;
    try {
      const response = await getMessaging(
        this.firebaseApp,
      ).sendEachForMulticast({
        tokens,
        notification: {
          title: payload.title,
          body: payload.body,
        },
        data: {
          reference: payload.reference,
          amount: payload.amount,
          direction: payload.direction,
          event: payload.event,
        },
      });
      if (response.failureCount > 0) {
        safeLogger.error('FCM partial failure', null, {
          userId,
          failures: response.failureCount,
        });
      }
    } catch (error) {
      safeLogger.error('FCM send failed', error, {
        userId,
        event: payload.event,
      });
    }
  }
}

import { Inject, Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import type { Cache } from 'cache-manager';
import { Repository } from 'typeorm';
import { getHeaderCacheKey } from '../../common/cache/http-cache.interceptor';
import { UserNotification } from './entities/user-notification.entity';

export interface UserNotificationDto {
  id: string;
  type: string;
  title: string;
  body: string;
  data: Record<string, unknown>;
  is_read: boolean;
  created_at: string;
  read_at: string | null;
}

@Injectable()
export class UserNotificationsService {
  constructor(
    @InjectRepository(UserNotification)
    private readonly repo: Repository<UserNotification>,
    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
  ) {}

  private async invalidateHeaderCache(userId: string): Promise<void> {
    try {
      await this.cacheManager.del(getHeaderCacheKey(userId));
    } catch {
      /* ignore cache errors */
    }
  }

  private toDto(row: UserNotification): UserNotificationDto {
    return {
      id: row.id,
      type: row.type,
      title: row.title,
      body: row.body,
      data: row.data ?? {},
      is_read: row.is_read,
      created_at: row.created_at.toISOString(),
      read_at: row.read_at ? row.read_at.toISOString() : null,
    };
  }

  async list(userId: string, limit = 20): Promise<UserNotificationDto[]> {
    const capped = Math.min(Math.max(limit, 1), 20);
    const rows = await this.repo.find({
      where: { user_id: userId },
      order: { created_at: 'DESC' },
      take: capped,
    });
    return rows.map((r) => this.toDto(r));
  }

  async unreadCount(userId: string): Promise<number> {
    return this.repo.count({ where: { user_id: userId, is_read: false } });
  }

  async markRead(userId: string, notificationId: string): Promise<UserNotificationDto> {
    const row = await this.repo.findOne({
      where: { id: notificationId, user_id: userId },
    });
    if (!row) {
      throw new NotFoundException('Notification not found');
    }
    if (!row.is_read) {
      row.is_read = true;
      row.read_at = new Date();
      await this.repo.save(row);
      await this.invalidateHeaderCache(userId);
    }
    return this.toDto(row);
  }

  async markAllRead(userId: string): Promise<{ updated: number }> {
    const result = await this.repo.update(
      { user_id: userId, is_read: false },
      { is_read: true, read_at: new Date() },
    );
    if ((result.affected ?? 0) > 0) {
      await this.invalidateHeaderCache(userId);
    }
    return { updated: result.affected ?? 0 };
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import {
  SecurityEvent,
  type SecurityEventType,
} from './entities/security-event.entity';
import { QuerySecurityEventsDto } from './dto/query-security-events.dto';

export interface CreateSecurityEventInput {
  user_id?: string | null;
  event_type: SecurityEventType;
  metadata?: Record<string, unknown> | null;
  ip_address?: string | null;
  device_id?: string | null;
}

@Injectable()
export class SecurityEventsService {
  constructor(
    @InjectRepository(SecurityEvent)
    private readonly securityEventRepository: Repository<SecurityEvent>,
  ) {}

  /**
   * High-volume path uses insert() (no entity hydration, no SELECT roundtrip).
   */
  async logEvent(input: CreateSecurityEventInput): Promise<void> {
    await this.securityEventRepository.insert(
      {
        user_id: input.user_id ?? null,
        event_type: input.event_type,
        metadata: input.metadata ?? null,
        ip_address: input.ip_address ?? null,
        device_id: input.device_id ?? null,
      } as any,
    );
  }

  async queryEvents(query: QuerySecurityEventsDto) {
    const limit = Math.min(query.limit ?? 100, 1000);
    const qb = this.securityEventRepository
      .createQueryBuilder('e')
      .orderBy('e.created_at', 'DESC')
      .take(limit);

    if (query.user_id) {
      qb.andWhere('e.user_id = :userId', { userId: query.user_id });
    }
    if (query.event_type) {
      qb.andWhere('e.event_type = :eventType', { eventType: query.event_type });
    }

    const rows = await qb.getMany();
    return rows.map((row) => ({
      id: row.id,
      user_id: row.user_id,
      event_type: row.event_type,
      metadata: row.metadata,
      ip: row.ip_address,
      deviceId: row.device_id,
      timestamp: row.created_at,
    }));
  }
}

import { isProductionRuntime } from '../../common/security/secrets';

export type SmsProviderName = 'envoisms' | 'twilio' | 'none';

/** Explicit provider, else prefer EnvoiSMS when keyed, else Twilio. */
export function resolveSmsProvider(
  env: NodeJS.ProcessEnv = process.env,
): SmsProviderName {
  const explicit = (env.SMS_PROVIDER || '').trim().toLowerCase();
  if (explicit === 'envoisms' || explicit === 'twilio' || explicit === 'none') {
    return explicit;
  }
  if (isEnvoiSmsConfigured(env)) return 'envoisms';
  if (isTwilioConfigured(env)) return 'twilio';
  return 'none';
}

export function isEnvoiSmsConfigured(
  env: NodeJS.ProcessEnv = process.env,
): boolean {
  return Boolean(env.ENVOISMS_API_KEY?.trim());
}

export function isTwilioConfigured(
  env: NodeJS.ProcessEnv = process.env,
): boolean {
  return Boolean(
    env.TWILIO_ACCOUNT_SID?.trim() &&
      env.TWILIO_AUTH_TOKEN?.trim() &&
      env.TWILIO_PHONE_NUMBER?.trim(),
  );
}

export function getEnvoiSmsBaseUrl(
  env: NodeJS.ProcessEnv = process.env,
): string {
  return (env.ENVOISMS_BASE_URL || 'https://api.envoisms.ma').replace(/\/$/, '');
}

export function getEnvoiSmsFrom(
  env: NodeJS.ProcessEnv = process.env,
): string | undefined {
  const from = env.ENVOISMS_FROM?.trim();
  return from || undefined;
}

/**
 * Production must have a real SMS provider.
 * Prefer EnvoiSMS (Morocco); Twilio remains an allowed fallback.
 */
export function assertProductionSmsConfigured(
  env: NodeJS.ProcessEnv = process.env,
): void {
  if (env.NODE_ENV !== 'production') return;
  if (env.NEXA_ENV === 'dogfood' && /^\d{6}$/.test((env.DEMO_OTP_CODE ?? '').trim())) {
    return;
  }
  const provider = resolveSmsProvider(env);
  if (provider === 'envoisms' && isEnvoiSmsConfigured(env)) return;
  if (provider === 'twilio' && isTwilioConfigured(env)) return;
  throw new Error(
    'SMS provider required in production. Set ENVOISMS_API_KEY (preferred) ' +
      'or TWILIO_ACCOUNT_SID + TWILIO_AUTH_TOKEN + TWILIO_PHONE_NUMBER. Mock SMS is disabled.',
  );
}

export { isProductionRuntime };

import { Injectable, Logger, OnModuleInit, Inject, Optional } from '@nestjs/common';
import { Twilio } from 'twilio';
import type { AlertingService } from '@nexa/telemetry';
import { ObsEvents } from '@nexa/telemetry';
import {
  assertProductionSmsConfigured,
  getEnvoiSmsBaseUrl,
  getEnvoiSmsFrom,
  isEnvoiSmsConfigured,
  isProductionRuntime,
  isTwilioConfigured,
  resolveSmsProvider,
  type SmsProviderName,
} from './sms-config';
import { ALERTING } from '../../common/observability/observability.tokens';

function maskPhone(phoneNumber: string): string {
  const digits = phoneNumber.replace(/\D/g, '');
  if (digits.length < 4) return '***';
  return `***${digits.slice(-4)}`;
}

function otpMessage(otpCode: string): string {
  return `Your Nexa Stays verification code is: ${otpCode}. Valid for 5 minutes. Do not share this code.`;
}

@Injectable()
export class SmsService implements OnModuleInit {
  private readonly logger = new Logger(SmsService.name);
  private provider: SmsProviderName = 'none';
  private twilioClient: Twilio | null = null;
  private twilioFromNumber = '';
  private envoiApiKey = '';
  private envoiBaseUrl = 'https://api.envoisms.ma';
  private envoiFrom: string | undefined;
  private isConfigured = false;

  constructor(
    @Optional() @Inject(ALERTING) private readonly alerting?: AlertingService,
  ) {}

  onModuleInit() {
    assertProductionSmsConfigured();

    this.provider = resolveSmsProvider();

    if (this.provider === 'envoisms' && isEnvoiSmsConfigured()) {
      this.envoiApiKey = process.env.ENVOISMS_API_KEY!.trim();
      this.envoiBaseUrl = getEnvoiSmsBaseUrl();
      this.envoiFrom = getEnvoiSmsFrom();
      this.isConfigured = true;
      this.logger.log(
        `EnvoiSMS service initialized (${this.envoiBaseUrl}${this.envoiFrom ? `, from=${this.envoiFrom}` : ''})`,
      );
      return;
    }

    if (this.provider === 'twilio' && isTwilioConfigured()) {
      const accountSid = process.env.TWILIO_ACCOUNT_SID!.trim();
      const authToken = process.env.TWILIO_AUTH_TOKEN!.trim();
      this.twilioFromNumber = process.env.TWILIO_PHONE_NUMBER!.trim();
      this.twilioClient = new Twilio(accountSid, authToken);
      this.isConfigured = true;
      this.logger.log('Twilio SMS service initialized');
      return;
    }

    this.logger.warn(
      'SMS provider not configured — OTP SMS delivery suppressed in non-production (OTP values are never logged)',
    );
  }

  async sendOtp(phoneNumber: string, otpCode: string): Promise<boolean> {
    return this.dispatch(phoneNumber, otpMessage(otpCode), true);
  }

  async sendGenericSms(phoneNumber: string, message: string): Promise<boolean> {
    return this.dispatch(phoneNumber, message, false);
  }

  isEnabled(): boolean {
    return this.isConfigured;
  }

  private async dispatch(
    phoneNumber: string,
    message: string,
    isOtp: boolean,
  ): Promise<boolean> {
    const masked = maskPhone(phoneNumber);

    if (!this.isConfigured) {
      if (isProductionRuntime()) {
        this.logger.error(
          `SMS provider not configured in production — refusing ${isOtp ? 'OTP ' : ''}delivery (${masked})`,
        );
        return false;
      }
      this.logger.warn(
        `[SMS Mock] ${isOtp ? 'OTP' : 'Generic SMS'} delivery suppressed in non-production for ${masked}`,
      );
      return true;
    }

    try {
      if (this.provider === 'envoisms') {
        const id = await this.sendViaEnvoiSms(phoneNumber, message, isOtp);
        this.logger.log(
          `SMS sent successfully to ${masked}${id ? `, id: ${id}` : ''} (envoisms)`,
        );
        return true;
      }

      if (this.provider === 'twilio' && this.twilioClient) {
        const result = await this.twilioClient.messages.create({
          body: message,
          from: this.twilioFromNumber,
          to: phoneNumber,
        });
        this.logger.log(
          `SMS sent successfully to ${masked}, SID: ${result.sid} (twilio)`,
        );
        return true;
      }

      this.logger.error(`SMS provider "${this.provider}" is not ready (${masked})`);
      return false;
    } catch {
      // Never log provider error bodies — they may echo message content/OTP.
      this.logger.error(`Failed to send SMS to ${masked}`);
      if (isOtp) {
        void this.alerting?.alert({
          key: ObsEvents.AUTH_OTP_PROVIDER_FAILURE,
          severity: 'P1',
          message: 'OTP SMS provider failure',
          fingerprint: 'auth:otp:provider',
          context: { phone_masked: masked, provider: this.provider },
        });
      }
      return false;
    }
  }

  /**
   * Deliver Nexa-generated OTP via EnvoiSMS POST /v1/messages.
   * We keep generating/verifying codes in Identity; EnvoiSMS's /v1/verify
   * would own a different code and break auth.service verifyOtp.
   * Docs: https://envoisms.ma/en/docs/
   */
  private async sendViaEnvoiSms(
    phoneNumber: string,
    message: string,
    isOtp: boolean,
  ): Promise<string | undefined> {
    const body: Record<string, unknown> = {
      to: phoneNumber,
      message,
      channel: 'sms',
    };
    if (this.envoiFrom) {
      body.from = this.envoiFrom;
    }
    if (isOtp) {
      body.metadata = { purpose: 'otp' };
    }

    const res = await fetch(`${this.envoiBaseUrl}/v1/messages`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${this.envoiApiKey}`,
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      // Drain body without logging — may contain echoed content.
      await res.text().catch(() => undefined);
      throw new Error(`EnvoiSMS HTTP ${res.status}`);
    }

    const payload = (await res.json().catch(() => null)) as
      | { id?: string }
      | null;
    return payload?.id;
  }
}

