  @Column({ type: 'boolean', default: false, name: 'identity_verified' })
  identity_verified: boolean;

  /** e.g. LEVEL_1, LEVEL_2, FULL */
  @Column({ type: 'varchar', length: 30, nullable: true, name: 'verification_level' })
