import {
  Entity,
  Column,
  PrimaryGeneratedColumn,
  CreateDateColumn,
  UpdateDateColumn,
  OneToOne,
  OneToMany,
  ManyToOne,
  JoinColumn,
} from 'typeorm';
import { UnifiedIdentity } from './unified-identity.entity';
import { KycProfile } from '../../compliance/entities/kyc-profile.entity';
import { AuditLog } from '../../audit/entities/audit-log.entity';
import { IdempotencyKey } from '../entities/idempotency-key.entity';

export const ACCOUNT_TYPES = [
  'CONSUMER',
  'DRIVER',
  'COURIER',
  'HOST',
  'MERCHANT',
  'ADMIN',
] as const;
export type AccountType = (typeof ACCOUNT_TYPES)[number];

export const STAFF_ROLES = ['ADMIN', 'SUPPORT_AGENT'] as const;
export type StaffRole = (typeof STAFF_ROLES)[number];

export function staffJwtClaims(
  staffRole: string | null | undefined,
): { role: StaffRole; roles: [StaffRole] } {
  const role: StaffRole =
    staffRole === 'SUPPORT_AGENT' ? 'SUPPORT_AGENT' : 'ADMIN';
  return { role, roles: [role] };
}

@Entity('users')
export class User {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  /**
   * Display/consistency. Canonical login identifiers in identity_phone_numbers.
   * Must match identity. Transitional; auth may resolve via identity first.
   * See backend/docs/unified-account-retirement-roadmap.md.
   */
  /** Nullable for ADMIN (email/password login); CONSUMER/DRIVER/etc. normally set. */
  @Column({ type: 'varchar', length: 20, nullable: true })
  phone_number: string | null;

  /** FK to unified_identities – canonical root for human identity. All service accounts attach here. */
  @Column({ type: 'uuid', name: 'unified_identity_id', nullable: true })
  unified_identity_id: string | null;

  @ManyToOne(() => UnifiedIdentity, (ui) => ui.users, { nullable: true, onDelete: 'SET NULL' })
  @JoinColumn({ name: 'unified_identity_id' })
  unified_identity: UnifiedIdentity | null;

  @Column({ type: 'varchar', length: 100, nullable: true })
  full_name: string;

  @Column({ type: 'varchar', length: 150, nullable: true })
  email: string;

  @Column({ type: 'varchar', length: 10, nullable: true })
  nationality: string;

  @Column({ type: 'text', nullable: true })
  city: string | null;

  @Column({ type: 'date', name: 'date_of_birth', nullable: true })
  date_of_birth: Date | null;

  @Column({ type: 'text', name: 'profile_photo_url', nullable: true })
  profile_photo_url: string | null;

  @Column({ type: 'timestamptz', name: 'profile_locked_at', nullable: true })
  profile_locked_at: Date | null;

  @UpdateDateColumn({ type: 'timestamptz', name: 'updated_at' })
  updated_at: Date;

  /** CONSUMER | DRIVER | COURIER | HOST | MERCHANT | ADMIN */
  @Column({
    type: 'varchar',
    length: 20,
    name: 'account_type',
    default: 'CONSUMER',
  })
  account_type: AccountType;

  /**
   * Dashboard staff authorization. Only meaningful when account_type = ADMIN.
   * ADMIN = Super Admin. SUPPORT_AGENT never appears together with ADMIN in JWT roles[].
   */
  @Column({
    type: 'varchar',
    length: 32,
    name: 'staff_role',
    default: 'ADMIN',
  })
  staff_role: StaffRole;

  /**
   * @deprecated Use getConsumerForIdentity(unified_identity_id) for payout resolution.
   * New role accounts leave null. Removal path: backend/docs/unified-account-retirement-roadmap.md.
   */
  @Column({ type: 'uuid', name: 'linked_user_id', nullable: true })
  linked_user_id: string | null;

  @ManyToOne(() => User, { nullable: true, onDelete: 'SET NULL' })
  @JoinColumn({ name: 'linked_user_id' })
  linked_user: User | null;

  @Column({ type: 'varchar', length: 20, default: 'PENDING' })
  kyc_status: string;

  @Column({ type: 'text' })
  pin_hash: string;

  /**
   * Argon2id hash for provisioned dashboard staff. Super Admin bootstrap
   * still uses ADMIN_EMAILS + env password. Never select in list APIs.
   */
  @Column({ type: 'text', name: 'staff_password_hash', nullable: true })
  staff_password_hash: string | null;

  @Column({ type: 'varchar', length: 20, default: 'ACTIVE' })
  status: string;

  /**
   * SEC-003: bumped on admin privilege revocation, freeze, or force-logout.
   * Access JWTs for ADMIN include claim `av` matching this value.
   */
  @Column({ type: 'int', name: 'authz_version', default: 1 })
  authz_version: number;

  @Column({ type: 'int', default: 0 })
  risk_score: number;

  @Column({ type: 'timestamp', name: 'last_login_at', nullable: true })
  last_login_at: Date;

  @Column({
    type: 'varchar',
    length: 30,
    name: 'deletion_status',
    default: 'NONE',
  })
  deletion_status: 'NONE' | 'PENDING' | 'ANONYMIZED';

  @Column({
    type: 'timestamptz',
    name: 'deletion_requested_at',
    nullable: true,
  })
  deletion_requested_at: Date | null;

  @Column({
    type: 'timestamptz',
    name: 'deletion_scheduled_for',
    nullable: true,
  })
  deletion_scheduled_for: Date | null;

  @Column({
    type: 'timestamptz',
    name: 'pii_anonymized_at',
    nullable: true,
  })
  pii_anonymized_at: Date | null;

  @CreateDateColumn({ type: 'timestamp', name: 'created_at' })
  created_at: Date;

  @OneToOne(() => KycProfile, (kyc) => kyc.user)
  kyc_profile: KycProfile;

  @OneToMany(() => AuditLog, (log) => log.user)
  audit_logs: AuditLog[];

  @OneToMany(() => IdempotencyKey, (key) => key.user)
  idempotency_keys: IdempotencyKey[];

  /** Nexa rewards program tier: standard | pro | premium */
  @Column({ type: 'varchar', length: 20, name: 'rewards_tier', default: 'standard' })
  rewards_tier: string;

  /** Cached Nexa Points balance; ledger is source of truth for history */
  @Column({ type: 'int', name: 'nexa_points', default: 0 })
  nexa_points: number;

  @Column({
    type: 'varchar',
    length: 32,
    name: 'rewards_referral_code',
    nullable: true,
    unique: true,
  })
  rewards_referral_code: string | null;

  @Column({
    type: 'boolean',
    name: 'rewards_kyc_completed',
    default: false,
  })
  rewards_kyc_completed: boolean;
}

import {
  Injectable,
  NotFoundException,
  ConflictException,
  BadRequestException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { IdentityPhoneNumber } from './entities/identity-phone-number.entity';
import { UnifiedIdentity } from './entities/unified-identity.entity';
import {
  normalizePhoneNumber,
  tryNormalizePhoneNumber,
} from '../../common/phone/phone-normalizer';

@Injectable()
export class IdentityPhoneNumbersService {
  constructor(
    @InjectRepository(IdentityPhoneNumber)
    private readonly repo: Repository<IdentityPhoneNumber>,
    @InjectRepository(UnifiedIdentity)
    private readonly identityRepo: Repository<UnifiedIdentity>,
  ) {}

  /**
   * Normalize phone to E.164. Re-export for convenience.
   */
  normalizePhoneNumber(raw: string): string {
    return normalizePhoneNumber(raw);
  }

  /** Try to normalize; returns null on failure. */
  tryNormalize(raw: string): string | null {
    return tryNormalizePhoneNumber(raw);
  }

  /**
   * Find identity by phone (via identity_phone_numbers).
   * Normalizes input before lookup. Returns null if not found.
   */
  async findIdentityByPhone(rawPhone: string): Promise<UnifiedIdentity | null> {
    const normalized = tryNormalizePhoneNumber(rawPhone);
    if (!normalized) return null;
    const row = await this.repo.findOne({
      where: { normalized_phone_number: normalized },
      relations: ['identity'],
    });
    return row?.identity ?? null;
  }

  /**
   * Find identity id by phone. Returns null if not found.
   */
  async findIdentityIdByPhone(rawPhone: string): Promise<string | null> {
    const normalized = tryNormalizePhoneNumber(rawPhone);
    if (!normalized) return null;
    const row = await this.repo.findOne({
      where: { normalized_phone_number: normalized },
      select: ['identity_id'],
    });
    return row?.identity_id ?? null;
  }

  /**
   * Attach a phone number to an identity.
   * Normalizes before storing. If number already linked to another identity, throws Conflict.
   * @param manager - Optional. When inside a transaction, pass the EntityManager so the identity
   *   lookup can see uncommitted rows (e.g. a freshly created unified_identity).
   */
  async attachPhoneNumberToIdentity(
    identityId: string,
    rawPhone: string,
    options?: { isPrimary?: boolean; isVerified?: boolean },
    manager?: EntityManager,
  ): Promise<IdentityPhoneNumber> {
    const identityRepo = manager
      ? manager.getRepository(UnifiedIdentity)
      : this.identityRepo;
    const repo = manager ? manager.getRepository(IdentityPhoneNumber) : this.repo;

    const identity = await identityRepo.findOne({
      where: { id: identityId },
    });
    if (!identity) {
      throw new NotFoundException('Identity not found');
    }
    const normalized = normalizePhoneNumber(rawPhone);
    const existing = await repo.findOne({
      where: { normalized_phone_number: normalized },
    });
    if (existing) {
      if (existing.identity_id === identityId) {
        return existing;
      }
      throw new ConflictException(
        'This phone number is already linked to another identity',
      );
    }
    const isFirst = (await repo.count({ where: { identity_id: identityId } })) === 0;
    const isPrimary = options?.isPrimary ?? isFirst;
    const isVerified = options?.isVerified ?? false;
    if (isPrimary) {
      await repo.update(
        { identity_id: identityId },
        { is_primary: false },
      );
    }
    const row = repo.create({
      identity_id: identityId,
      phone_number: rawPhone,
      normalized_phone_number: normalized,
      is_primary: isPrimary,
      is_verified: isVerified,
      verified_at: isVerified ? new Date() : null,
    });
    try {
      return await repo.save(row);
    } catch (e: any) {
      if (e?.code === '23505') {
        const existingRow = await repo.findOne({
          where: { normalized_phone_number: normalized },
        });
        if (existingRow?.identity_id === identityId) {
          return existingRow;
        }
        throw new ConflictException(
          'This phone number is already linked to another identity',
        );
      }
      throw e;
    }
  }

  /**
   * Set the primary phone number for an identity.
   */
  async setPrimaryPhoneNumber(
    identityId: string,
    rawPhone: string,
  ): Promise<IdentityPhoneNumber> {
    const normalized = normalizePhoneNumber(rawPhone);
    const row = await this.repo.findOne({
      where: {
        identity_id: identityId,
        normalized_phone_number: normalized,
      },
    });
    if (!row) {
      throw new NotFoundException(
        'Phone number not found for this identity',
      );
    }
    await this.repo.update(
      { identity_id: identityId },
      { is_primary: false },
    );
    row.is_primary = true;
    return this.repo.save(row);
  }

  /**
   * Mark a phone number as verified.
   */
  async verifyPhoneNumber(
    identityId: string,
    rawPhone: string,
  ): Promise<IdentityPhoneNumber> {
    const normalized = normalizePhoneNumber(rawPhone);
    const row = await this.repo.findOne({
      where: {
        identity_id: identityId,
        normalized_phone_number: normalized,
      },
    });
    if (!row) {
      throw new NotFoundException(
        'Phone number not found for this identity',
      );
    }
    row.is_verified = true;
    row.verified_at = new Date();
    return this.repo.save(row);
  }

  /**
   * Get primary phone for an identity, or first phone if none primary.
   */
  async getPrimaryPhone(identityId: string): Promise<string | null> {
    const primary = await this.repo.findOne({
      where: { identity_id: identityId, is_primary: true },
      select: ['phone_number'],
    });
    if (primary) return primary.phone_number;
    const first = await this.repo.findOne({
      where: { identity_id: identityId },
      order: { created_at: 'ASC' },
      select: ['phone_number'],
    });
    return first?.phone_number ?? null;
  }
}

import {
  Controller,
  Get,
  NotFoundException,
  Param,
  Res,
  UseGuards,
} from '@nestjs/common';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import { createReadStream } from 'fs';
import * as path from 'path';
import type { Response } from 'express';
import { Public } from '../../common/decorators/public.decorator';
import { InternalServiceGuard } from '../../common/guards/internal-service.guard';
import { UsersService } from './users.service';

@ApiTags('internal-users')
@Controller('internal/users')
@Public()
@UseGuards(InternalServiceGuard)
export class InternalUsersController {
  constructor(private readonly usersService: UsersService) {}

  /** Must be declared before `:userId` routes so "support-agents" is not captured as an id. */
  @Get('support-agents')
  @ApiOperation({
    summary: 'S2S: ACTIVE SUPPORT_AGENT roster for ticket auto-assignment',
  })
  async listActiveSupportAgents(): Promise<{
    items: { id: string; status: string; staff_role: string }[];
  }> {
    return this.usersService.listActiveSupportAgents();
  }

  @Get(':userId/authz')
  @ApiOperation({ summary: 'S2S: authz version for ADMIN role revocation checks' })
  async authzState(
    @Param('userId') userId: string,
  ): Promise<{
    authz_version: number;
    status: string;
    account_type: string;
    staff_role: string;
  }> {
    const user = await this.usersService.findById(userId);
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return {
      authz_version: Number(user.authz_version ?? 1),
      status: user.status,
      account_type: user.account_type,
      staff_role: user.staff_role || 'ADMIN',
    };
  }

  @Get(':userId/profile-photo/exists')
  @ApiOperation({ summary: 'S2S: whether user has an uploaded profile photo' })
  async profilePhotoExists(@Param('userId') userId: string): Promise<{ hasPhoto: boolean }> {
    const filePath = await this.usersService.getProfilePhotoPath(userId);
    return { hasPhoto: !!filePath };
  }

  @Get(':userId/profile-photo')
  @ApiOperation({ summary: 'S2S: stream user profile photo bytes' })
  async getProfilePhoto(
    @Param('userId') userId: string,
    @Res() res: Response,
  ): Promise<void> {
    const filePath = await this.usersService.getProfilePhotoPath(userId);
    if (!filePath) {
      throw new NotFoundException('No profile photo');
    }
    const resolved = path.resolve(filePath);
    const photoRoot = path.resolve('uploads/profile');
    if (
      resolved !== photoRoot &&
      !resolved.startsWith(photoRoot + path.sep)
    ) {
      throw new NotFoundException('No profile photo');
    }
    const ext = resolved.split('.').pop()?.toLowerCase();
    const contentType =
      ext === 'png'
        ? 'image/png'
        : ext === 'jpg' || ext === 'jpeg'
          ? 'image/jpeg'
          : 'application/octet-stream';
    res.setHeader('Content-Type', contentType);
    res.setHeader('Cache-Control', 'private, max-age=3600');
    createReadStream(resolved).pipe(res);
  }

  @Get(':userId/profile-summary')
  @ApiOperation({ summary: 'S2S: minimal profile for messaging presentation' })
  async profileSummary(
    @Param('userId') userId: string,
  ): Promise<{
    fullName: string | null;
    email: string | null;
    phone: string | null;
    verified: boolean;
    preferredLanguage: string | null;
  }> {
    const user = await this.usersService.findById(userId);
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return {
      fullName: user.full_name?.trim() || null,
      email: user.email?.trim() || null,
      phone: user.phone_number?.trim() || null,
      verified: user.kyc_status === 'VERIFIED',
      preferredLanguage: await this.usersService.getPreferredLanguageForUser(
        user.unified_identity_id,
      ),
    };
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ReusableIdentityVerification } from './entities/reusable-identity-verification.entity';
import { KycProfile } from '../compliance/entities/kyc-profile.entity';
import { UnifiedIdentityService } from './unified-identity.service';
import { NexaService, getServicePolicy } from './kyc-reuse-policy';

export interface KycReuseResult {
  useExistingKyc: boolean;
  canSkipIdentityStep: boolean;
  canPrefillIdentityReadonly: boolean;
  requireStepUpVerification: boolean;
  isDocumentExpired: boolean;
  isReusableForService: boolean;
  blockReason: string | null;
  verification: ReusableIdentityVerification | null;
}

@Injectable()
export class KycReuseService {
  constructor(
    @InjectRepository(ReusableIdentityVerification)
    private readonly repo: Repository<ReusableIdentityVerification>,
    private readonly unifiedIdentityService: UnifiedIdentityService,
  ) {}

  /**
   * Whether KYC can be reused for this service. Only APPROVED/VERIFIED, non-expired, policy-allowed.
   */
  isKycReusableForService(
    verification: ReusableIdentityVerification | null,
    service: NexaService,
  ): boolean {
    if (!verification) return false;
    const policy = getServicePolicy(service);
    if (!policy.allowsReuse) return false;
    const isVerified =
      verification.verification_status === 'APPROVED' ||
      verification.kyc_status === 'VERIFIED' ||
      verification.kyc_status === 'APPROVED';
    if (!isVerified) return false;
    if (!verification.identity_verified) return false;
    if (verification.reusable_across_services === false) return false;
    if (verification.reuse_block_reason) return false;
    if (this.isIdentityDocumentExpired(verification)) return false;
    if (policy.minVerificationLevel && verification.verification_level) {
      if (verification.verification_level !== policy.minVerificationLevel) {
        return false;
      }
    }
    if (
      policy.acceptedDocumentTypes?.length &&
      verification.document_type &&
      !policy.acceptedDocumentTypes.includes(verification.document_type)
    ) {
      return false;
    }
    return true;
  }

  /** Document expiry: past expiry_date = expired */
  isIdentityDocumentExpired(
    verification: ReusableIdentityVerification | null,
  ): boolean {
    if (!verification?.expiry_date) return false;
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const exp = verification.expiry_date instanceof Date
      ? verification.expiry_date
      : new Date(verification.expiry_date);
    exp.setHours(0, 0, 0, 0);
    return exp < now;
  }

  /**
   * Whether identity verification step can be skipped (reuse existing valid KYC).
   */
  canSkipIdentityStep(
    unifiedIdentityId: string,
    service: NexaService,
  ): Promise<boolean> {
    return this.useExistingKyc(unifiedIdentityId, service).then(
      (r) => r.useExistingKyc,
    );
  }

  /**
   * Can prefill identity fields as read-only (even if step-up required).
   */
  canPrefillIdentityReadonly(service: NexaService): boolean {
    return getServicePolicy(service).canPrefillIdentityReadonly;
  }

  /**
   * Whether this service requires step-up verification (e.g. driver license, vehicle).
   */
  requireStepUpVerification(service: NexaService): boolean {
    return getServicePolicy(service).requiresStepUpVerification;
  }

  /**
   * Main entry: can we use existing KYC for this service?
   * Returns full result for use_existing_kyc, can_skip_identity_step, etc.
   */
  async useExistingKyc(
    unifiedIdentityId: string,
    service: NexaService,
  ): Promise<KycReuseResult> {
    const policy = getServicePolicy(service);
    const verification = await this.repo.findOne({
      where: { unified_identity_id: unifiedIdentityId },
    });

    const isDocumentExpired = this.isIdentityDocumentExpired(verification ?? null);
    const isReusableForService = this.isKycReusableForService(
      verification ?? null,
      service,
    );

    const isVerified =
      verification?.verification_status === 'APPROVED' ||
      verification?.kyc_status === 'VERIFIED' ||
      verification?.kyc_status === 'APPROVED';
    let blockReason: string | null = null;
    if (!verification) {
      blockReason = 'NO_REUSABLE_KYC';
    } else if (!isVerified) {
      blockReason = 'NOT_VERIFIED';
    } else if (verification.reuse_block_reason) {
      blockReason = verification.reuse_block_reason;
    } else if (isDocumentExpired) {
      blockReason = 'EXPIRED';
    } else if (!policy.allowsReuse) {
      blockReason = 'POLICY';
    }

    const useExistingKyc = isReusableForService && !blockReason;
    const canSkipIdentityStep = useExistingKyc && !policy.requiresStepUpVerification;
    const canPrefillIdentityReadonly =
      policy.canPrefillIdentityReadonly &&
      verification != null &&
      isVerified &&
      !isDocumentExpired;

    return {
      useExistingKyc,
      canSkipIdentityStep,
      canPrefillIdentityReadonly,
      requireStepUpVerification: policy.requiresStepUpVerification,
      isDocumentExpired,
      isReusableForService,
      blockReason,
      verification: verification ?? null,
    };
  }

  /**
   * Find reusable verification for unified identity (read-only).
   */
  async findByUnifiedIdentity(
    unifiedIdentityId: string,
  ): Promise<ReusableIdentityVerification | null> {
    return this.repo.findOne({
      where: { unified_identity_id: unifiedIdentityId },
    });
  }

  /**
   * Create or update reusable verification from a verified KycProfile.
   * Called when admin approves KYC or when KYC flow completes.
   */
  async upsertFromKycProfile(params: {
    unifiedIdentityId: string;
    kycProvider: string | null;
    verificationReference: string | null;
    verificationLevel: string | null;
    documentType: string | null;
    documentNumberMasked: string | null;
    expiryDate: Date | null;
    selfieVerified: boolean;
  }): Promise<ReusableIdentityVerification> {
    const now = new Date();
    const existing = await this.repo.findOne({
      where: { unified_identity_id: params.unifiedIdentityId },
    });

    const payload = {
      kyc_provider: params.kycProvider,
      verification_reference: params.verificationReference,
      kyc_status: 'VERIFIED',
      verification_status: 'APPROVED' as const,
      identity_verified: true,
      verification_level: params.verificationLevel,
      document_type: params.documentType,
      document_number_masked: params.documentNumberMasked,
      first_verified_at: existing?.first_verified_at ?? now,
      last_verified_at: now,
      expiry_date: params.expiryDate,
      selfie_verified: params.selfieVerified,
      reusable_across_services: true,
      reuse_block_reason: null,
    };

    if (existing) {
      await this.repo.update(existing.id, payload);
      const updated = await this.repo.findOne({ where: { id: existing.id } });
      if (!updated) throw new Error('ReusableIdentityVerification not found after update');
      return updated;
    }

    const created = this.repo.create({
      unified_identity_id: params.unifiedIdentityId,
      ...payload,
    });
    return this.repo.save(created);
  }

  /**
   * Sync reusable verification from a freshly approved KycProfile.
   * Call after admin approves KYC. Ensures unified identity exists, then upserts.
   */
  async syncFromKycApproval(
    userPhoneNumber: string,
    kyc: KycProfile,
  ): Promise<ReusableIdentityVerification | null> {
    const identity = await this.unifiedIdentityService.findOrCreateByPhone(userPhoneNumber);
    const selfieVerified = Boolean(kyc.documents?.selfie ?? kyc.selfie_url);
    let documentNumberMasked: string | null = null;
    if (kyc.national_id_number) {
      const s = String(kyc.national_id_number);
      documentNumberMasked = s.length > 4 ? `****${s.slice(-4)}` : '****';
    }
    let expiryDate: Date | null = null;
    // KycProfile does not have expiry_date; could be added or derived from document_type
    const reusable = await this.upsertFromKycProfile({
      unifiedIdentityId: identity.id,
      kycProvider: kyc.provider ?? null,
      verificationReference: kyc.reference ?? null,
      verificationLevel: kyc.level ?? null,
      documentType: kyc.document_type ?? null,
      documentNumberMasked,
      expiryDate,
      selfieVerified,
    });
    await this.unifiedIdentityService.updateKycStatus(
      identity.id,
      true,
      'VERIFIED',
    );
    return reusable;
  }

  /**
   * Mark reusable verification as blocked (e.g. document expired, admin revoke).
   */
  async setReuseBlocked(
    unifiedIdentityId: string,
    reason: string,
  ): Promise<void> {
    await this.repo.update(
      { unified_identity_id: unifiedIdentityId },
      {
        reusable_across_services: false,
        reuse_block_reason: reason,
        updated_at: new Date(),
      },
    );
  }
}

/**
 * Profile Sync Policy – field-level rules for data sync across Nexa services.
 * UnifiedIdentity is source of truth for shared fields.
 * Service-specific fields never overwrite global data.
 */

import type { NexaService } from './nexa-services';

export type { NexaService };
export type ConflictStrategy =
  | 'UNIFIED_WINS'     // UnifiedIdentity always wins; overwrite local
  | 'LATEST_WINS'      // Most recent update wins (timestamp compare)
  | 'VERIFIED_WINS'    // KYC-verified value wins over unverified
  | 'NO_OVERWRITE'     // Never overwrite existing non-null value
  | 'MANUAL_RESOLVE';  // Flag for admin resolution

export type SharedField =
  | 'full_name'
  | 'email'
  | 'date_of_birth'
  | 'city'
  | 'address'
  | 'profile_photo_url'
  | 'preferred_language';

export interface FieldSyncRule {
  field: SharedField;
  source_of_truth: 'UNIFIED_IDENTITY';
  writable_from_services: NexaService[];
  requires_verification: boolean;
  conflict_strategy: ConflictStrategy;
  audit_required: boolean;
}

/** Shared fields: sync across Pay, Go, Stays, Driver. Source of truth = UnifiedIdentity. */
export const SHARED_FIELDS: SharedField[] = [
  'full_name',
  'email',
  'date_of_birth',
  'city',
  'address',
  'profile_photo_url',
  'preferred_language',
];

/** Fields that must remain service-specific – never sync. */
export const SERVICE_SPECIFIC_FIELDS = [
  'wallet_balance',
  'payment_methods',
  'rides_history',
  'stays_bookings',
  'host_settings',
  'vehicle_details',
  'driver_documents',
  'insurance',
  'background_checks',
  'payout_methods',
  'kyc_status',           // Per-user KYC state; verification flows only
  'profile_locked_at',    // Per-user lock from KYC
  'linked_user_id',       // Role linking
  'risk_score',
  'last_login_at',
] as const;

export const PROFILE_SYNC_RULES: Record<SharedField, FieldSyncRule> = {
  full_name: {
    field: 'full_name',
    source_of_truth: 'UNIFIED_IDENTITY',
    writable_from_services: ['PAY', 'GO', 'STAYS', 'DRIVER', 'COURIER', 'HOST', 'MERCHANT'],
    requires_verification: true,  // Locked after KYC
    conflict_strategy: 'VERIFIED_WINS',
    audit_required: true,
  },
  email: {
    field: 'email',
    source_of_truth: 'UNIFIED_IDENTITY',
    writable_from_services: ['PAY', 'GO', 'STAYS', 'DRIVER', 'COURIER', 'HOST', 'MERCHANT'],
    requires_verification: false,
    conflict_strategy: 'LATEST_WINS',
    audit_required: true,
  },
  date_of_birth: {
    field: 'date_of_birth',
    source_of_truth: 'UNIFIED_IDENTITY',
    writable_from_services: ['PAY', 'GO', 'STAYS', 'DRIVER', 'COURIER', 'HOST', 'MERCHANT'],
    requires_verification: true,
    conflict_strategy: 'VERIFIED_WINS',
    audit_required: true,
  },
  city: {
    field: 'city',
    source_of_truth: 'UNIFIED_IDENTITY',
    writable_from_services: ['PAY', 'GO', 'STAYS', 'DRIVER', 'COURIER', 'HOST', 'MERCHANT'],
    requires_verification: false,
    conflict_strategy: 'LATEST_WINS',
    audit_required: false,
  },
  address: {
    field: 'address',
    source_of_truth: 'UNIFIED_IDENTITY',
    writable_from_services: ['PAY', 'GO', 'STAYS', 'DRIVER', 'COURIER', 'HOST', 'MERCHANT'],
    requires_verification: false,
    conflict_strategy: 'LATEST_WINS',
    audit_required: false,
  },
  profile_photo_url: {
    field: 'profile_photo_url',
    source_of_truth: 'UNIFIED_IDENTITY',
    writable_from_services: ['PAY', 'GO', 'STAYS', 'DRIVER', 'COURIER', 'HOST', 'MERCHANT'],
    requires_verification: false,
    conflict_strategy: 'LATEST_WINS',
    audit_required: true,
  },
  preferred_language: {
    field: 'preferred_language',
    source_of_truth: 'UNIFIED_IDENTITY',
    writable_from_services: ['PAY', 'GO', 'STAYS', 'DRIVER', 'COURIER', 'HOST', 'MERCHANT'],
    requires_verification: false,
    conflict_strategy: 'LATEST_WINS',
    audit_required: false,
  },
};

export function getFieldRule(field: SharedField): FieldSyncRule {
  return PROFILE_SYNC_RULES[field];
}

export function isSharedField(field: string): field is SharedField {
  return SHARED_FIELDS.includes(field as SharedField);
}

export function canWriteFromService(
  field: SharedField,
  service: NexaService,
): boolean {
  return PROFILE_SYNC_RULES[field].writable_from_services.includes(service);
}

/** Map account_type to primary NexaService for sync context. */
export function accountTypeToService(accountType: string): NexaService {
  const t = (accountType ?? 'CONSUMER').toUpperCase();
  if (t === 'DRIVER') return 'DRIVER';
  if (t === 'COURIER') return 'COURIER';
  if (t === 'HOST') return 'HOST';
  if (t === 'MERCHANT') return 'MERCHANT';
  return 'PAY';
}

import {
  Injectable,
  ForbiddenException,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { UnifiedIdentity } from './entities/unified-identity.entity';
import { User } from './entities/user.entity';
import {
  SharedField,
  NexaService,
  PROFILE_SYNC_RULES,
  getFieldRule,
  isSharedField,
  canWriteFromService,
  ConflictStrategy,
} from './profile-sync-policy';
import { AuditService } from '../audit/audit.service';
import type { Request } from 'express';

export interface SharedProfileUpdate {
  full_name?: string | null;
  email?: string | null;
  date_of_birth?: Date | string | null;
  city?: string | null;
  address?: string | null;
  profile_photo_url?: string | null;
  preferred_language?: string | null;
}

export interface ProfileSyncOptions {
  service: NexaService;
  userId: string;
  unifiedIdentityId: string;
  profileLocked?: boolean;
  identityVerified?: boolean;
  auditParams?: {
    actorUserId: string;
    actorRole?: string;
    req?: Request | null;
  };
}

export interface SyncResult {
  updated: boolean;
  unifiedIdentityUpdated: boolean;
  usersPropagated: number;
  fieldsUpdated: string[];
  fieldsSkipped: string[];
  conflicts: { field: SharedField; reason: string }[];
}

@Injectable()
export class ProfileSyncService {
  constructor(
    @InjectRepository(UnifiedIdentity)
    private readonly unifiedRepo: Repository<UnifiedIdentity>,
    @InjectRepository(User)
    private readonly userRepo: Repository<User>,
    private readonly auditService: AuditService,
  ) {}

  /**
   * Update shared profile fields. Writes to UnifiedIdentity (source of truth), then propagates to linked users.
   * Validates writable_from_services, requires_verification (locked fields), conflict_strategy.
   */
  async updateSharedProfile(
    updates: SharedProfileUpdate,
    options: ProfileSyncOptions,
  ): Promise<SyncResult> {
    const identity = await this.unifiedRepo.findOne({
      where: { id: options.unifiedIdentityId },
    });
    if (!identity) {
      throw new NotFoundException('Unified identity not found');
    }

    const fieldsUpdated: string[] = [];
    const fieldsSkipped: string[] = [];
    const conflicts: { field: SharedField; reason: string }[] = [];

    const payload: Partial<UnifiedIdentity> = {};
    const lockedFields = options.profileLocked
      ? ['full_name', 'date_of_birth']
      : [];

    for (const [key, value] of Object.entries(updates)) {
      if (value === undefined) continue;
      if (!isSharedField(key)) {
        fieldsSkipped.push(`${key} (not a shared field)`);
        continue;
      }

      const rule = getFieldRule(key);
      if (!canWriteFromService(key, options.service)) {
        fieldsSkipped.push(`${key} (service not allowed)`);
        continue;
      }
      if (rule.requires_verification && lockedFields.includes(key)) {
        fieldsSkipped.push(`${key} (locked by KYC)`);
        conflicts.push({ field: key, reason: 'FIELD_LOCKED_KYC' });
        continue;
      }

      let valueToStore = value;
      if (key === 'date_of_birth' && typeof value === 'string') {
        valueToStore = new Date(value);
      }
      const currentValue = (identity as unknown as Record<string, unknown>)[key];
      const strategy = this.resolveConflict(
        key,
        currentValue,
        valueToStore,
        identity.identity_verified ?? false,
        rule.conflict_strategy,
      );
      if (strategy === 'SKIP') {
        fieldsSkipped.push(`${key} (conflict: ${rule.conflict_strategy})`);
        conflicts.push({ field: key, reason: `CONFLICT_${rule.conflict_strategy}` });
        continue;
      }

      (payload as Record<string, unknown>)[key] = valueToStore;
      fieldsUpdated.push(key);
    }

    let unifiedIdentityUpdated = false;
    if (Object.keys(payload).length > 0) {
      await this.unifiedRepo.update(options.unifiedIdentityId, {
        ...payload,
        updated_at: new Date(),
      });
      unifiedIdentityUpdated = true;

      for (const field of fieldsUpdated) {
        const rule = getFieldRule(field as SharedField);
        if (rule.audit_required && options.auditParams) {
          await this.auditService.audit({
            actorUserId: options.auditParams.actorUserId,
            actorRole: options.auditParams.actorRole ?? undefined,
            action: 'PROFILE_SYNC_UPDATE',
            targetType: 'unified_identity',
            targetId: options.unifiedIdentityId,
            metadata: {
              field,
              service: options.service,
              unifiedIdentityId: options.unifiedIdentityId,
            },
            req: options.auditParams.req ?? undefined,
          });
        }
      }
    }

    const usersPropagated = await this.propagateToUsers(
      options.unifiedIdentityId,
      payload,
    );

    return {
      updated: fieldsUpdated.length > 0,
      unifiedIdentityUpdated,
      usersPropagated,
      fieldsUpdated,
      fieldsSkipped,
      conflicts,
    };
  }

  /**
   * Propagate shared fields from UnifiedIdentity to all linked users (cache refresh).
   */
  async syncFromUnifiedToUsers(unifiedIdentityId: string): Promise<number> {
    const identity = await this.unifiedRepo.findOne({
      where: { id: unifiedIdentityId },
    });
    if (!identity) return 0;

    const payload: Partial<User> = {};
    const userFields = ['full_name', 'email', 'city', 'date_of_birth', 'profile_photo_url'] as const;
    for (const f of userFields) {
      const idRec = identity as unknown as Record<string, unknown>;
      if (idRec[f] !== undefined) {
        (payload as Record<string, unknown>)[f] = idRec[f];
      }
    }
    if (Object.keys(payload).length === 0) return 0;
    return this.propagateToUsers(unifiedIdentityId, payload);
  }

  /**
   * Resolve conflict between current and incoming value.
   * Returns 'APPLY' to apply the update, 'SKIP' to skip.
   */
  private resolveConflict(
    field: SharedField,
    current: unknown,
    incoming: unknown,
    identityVerified: boolean,
    strategy: ConflictStrategy,
  ): 'APPLY' | 'SKIP' {
    const currentEmpty = current == null || current === '';
    const incomingEmpty = incoming == null || incoming === '';

    if (incomingEmpty && !currentEmpty) return 'SKIP';
    if (currentEmpty) return 'APPLY';

    switch (strategy) {
      case 'UNIFIED_WINS':
        return 'APPLY';
      case 'NO_OVERWRITE':
        return 'SKIP';
      case 'LATEST_WINS':
        return 'APPLY';
      case 'VERIFIED_WINS':
        return identityVerified ? 'APPLY' : 'SKIP';
      case 'MANUAL_RESOLVE':
        return 'SKIP';
      default:
        return 'APPLY';
    }
  }

  private async propagateToUsers(
    unifiedIdentityId: string,
    payload: Partial<UnifiedIdentity> | Partial<User>,
  ): Promise<number> {
    const userPayload: Partial<User> = {};
    const allowed = ['full_name', 'email', 'city', 'date_of_birth', 'profile_photo_url'];
    for (const k of allowed) {
      const v = (payload as Record<string, unknown>)[k];
      if (v !== undefined) (userPayload as Record<string, unknown>)[k] = v;
    }
    if (Object.keys(userPayload).length === 0) return 0;

    const result = await this.userRepo
      .createQueryBuilder()
      .update(User)
      .set({ ...userPayload, updated_at: new Date() })
      .where('unified_identity_id = :id', { id: unifiedIdentityId })
      .execute();
    return result.affected ?? 0;
  }

  /**
   * Check if a field can be written from the given service.
   */
  canWrite(field: SharedField, service: NexaService): boolean {
    return canWriteFromService(field, service);
  }

  /**
   * Check if a field requires verification (KYC lock).
   */
  isFieldLockedAfterKyc(field: SharedField): boolean {
    return PROFILE_SYNC_RULES[field].requires_verification;
  }
}

/**
 * Role categories for branching logic between person-based and business-based roles.
 * See docs/merchant-business-entity-evolution.md for evolution path.
 *
 * - PERSON_ROLES: Individual human identities (profile = person data)
 * - BUSINESS_ROLES: Currently MERCHANT only; modeled as person today but may evolve
 *   to MerchantOrganization with operators/branches
 */
import type { AccountType } from './entities/user.entity';

/** Roles that represent an individual person; profile fields (full_name, date_of_birth) apply directly. */
export const PERSON_ROLES: readonly AccountType[] = [
  'CONSUMER',
  'DRIVER',
  'COURIER',
  'HOST',
] as const;

/**
 * Roles that may represent or operate a business entity.
 * Today MERCHANT is person-scoped (one User = one operator); future: MerchantOrganization + operators.
 */
export const BUSINESS_CAPABLE_ROLES: readonly AccountType[] = ['MERCHANT'] as const;

export function isPersonRole(accountType: string | null | undefined): boolean {
  return (
    (accountType ?? '').length > 0 &&
    (PERSON_ROLES as readonly string[]).includes((accountType ?? '').toUpperCase())
  );
}

/**
 * Roles that typically need linked_user → CONSUMER for payouts.
 * MERCHANT excluded: operator may not need consumer link; business entity may have different payout model.
 */
export function roleUsesConsumerForPayout(accountType: string | null | undefined): boolean {
  return ['DRIVER', 'COURIER', 'HOST'].includes((accountType ?? '').toUpperCase());
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DataSource, EntityManager, Repository } from 'typeorm';
import { UnifiedIdentity } from './entities/unified-identity.entity';
import { User } from './entities/user.entity';
import { IdentityPhoneNumbersService } from './identity-phone-numbers.service';
import { tryNormalizePhoneNumber, phoneLookupCandidates } from '../../common/phone/phone-normalizer';

export interface UnifiedProfileResult {
  id: string;
  phone_number: string;
  full_name: string | null;
  email: string | null;
  date_of_birth: string | null;
  city: string | null;
  address: string | null;
  kyc_status: string;
  identity_verified: boolean;
  linked_services: string[];
}

@Injectable()
export class UnifiedIdentityService {
  constructor(
    @InjectRepository(UnifiedIdentity)
    private readonly unifiedIdentityRepo: Repository<UnifiedIdentity>,
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly identityPhoneNumbersService: IdentityPhoneNumbersService,
    private readonly dataSource: DataSource,
  ) {}

  /**
   * Find unified identity by phone, or create one if none exists.
   * Uses advisory lock to prevent duplicate identities under concurrent requests.
   */
  /**
   * Bootstrap a UnifiedIdentity for email-only ADMIN (no phone). Required for JWT claims
   * and refresh-token rotation consistency.
   */
  async ensureIdentityForAdminUser(userId: string): Promise<string> {
    const user = await this.userRepository.findOne({
      where: { id: userId },
      select: ['id', 'unified_identity_id', 'email', 'full_name'],
    });
    if (!user) throw new NotFoundException('User not found');
    if (user.unified_identity_id) return user.unified_identity_id;

    const identity = this.unifiedIdentityRepo.create({
      phone_number: null,
      email: user.email?.trim()?.toLowerCase() || null,
      full_name: user.full_name ?? null,
      kyc_status: 'APPROVED',
      identity_verification_status: 'APPROVED',
      identity_verified: true,
      account_status: 'ACTIVE',
      linked_services: ['ADMIN'],
    });
    const saved = await this.unifiedIdentityRepo.save(identity);
    await this.userRepository.update(user.id, {
      unified_identity_id: saved.id,
    });
    return saved.id;
  }

  async findOrCreateByPhone(phoneNumber: string): Promise<UnifiedIdentity> {
    const norm = tryNormalizePhoneNumber(phoneNumber) ?? phoneNumber;
    return this.dataSource.transaction(async (manager) => {
      await manager.query(
        'SELECT pg_advisory_xact_lock(hashtext($1))',
        [norm],
      );
      const existing = await this.findIdentityByPhoneOrLegacy(phoneNumber);
      if (existing) {
        await this.linkUsersToIdentity(phoneNumber, existing.id);
        await this.ensurePhoneAttached(existing.id, phoneNumber, manager);
        return existing;
      }
      const candidates = phoneLookupCandidates(phoneNumber);
      const users = await this.userRepository
        .createQueryBuilder('u')
        .select(['u.id', 'u.account_type', 'u.full_name', 'u.email', 'u.date_of_birth', 'u.city', 'u.profile_photo_url', 'u.kyc_status', 'u.status'])
        .where('u.phone_number IN (:...candidates)', { candidates })
        .orderBy("CASE WHEN u.account_type = 'CONSUMER' THEN 0 ELSE 1 END")
        .addOrderBy('u.created_at')
        .getMany();

      if (users.length === 0) {
        const identity = this.unifiedIdentityRepo.create({
          phone_number: phoneNumber,
          kyc_status: 'PENDING',
          identity_verification_status: 'NOT_STARTED',
          account_status: 'ACTIVE',
          linked_services: [],
        });
        const saved = await manager.save(UnifiedIdentity, identity);
        await this.ensurePhoneAttached(saved.id, phoneNumber, manager);
        return saved;
      }

      const consumer = users.find((u) => u.account_type === 'CONSUMER');
      const best = consumer ?? users[0];
      const linkedServices = Array.from(
        new Set(users.map((u) => String(u.account_type ?? 'CONSUMER'))),
      );
      const legacyStatus = (best.kyc_status ?? 'PENDING').toUpperCase();
      const identityVerified =
        legacyStatus === 'APPROVED' || legacyStatus === 'VERIFIED';
      const identity = this.unifiedIdentityRepo.create({
        phone_number: phoneNumber,
        full_name: best.full_name ?? null,
        email: best.email ?? null,
        date_of_birth: best.date_of_birth ?? null,
        city: best.city ?? null,
        profile_photo_url: best.profile_photo_url ?? null,
        identity_verified: identityVerified,
        kyc_status: best.kyc_status ?? 'PENDING',
        identity_verification_status: identityVerified
          ? 'APPROVED'
          : legacyStatus === 'REJECTED'
            ? 'REJECTED'
            : 'PENDING',
        account_status: best.status ?? 'ACTIVE',
        linked_services: linkedServices,
      });
      const saved = await manager.save(UnifiedIdentity, identity);
      await this.linkUsersToIdentity(phoneNumber, saved.id);
      await this.ensurePhoneAttached(saved.id, phoneNumber, manager);
      return saved;
    });
  }

  /**
   * Find identity by phone via identity_phone_numbers, or legacy unified_identities.phone_number.
   */
  private async findIdentityByPhoneOrLegacy(
    phoneNumber: string,
  ): Promise<UnifiedIdentity | null> {
    for (const candidate of phoneLookupCandidates(phoneNumber)) {
      const viaTable = await this.identityPhoneNumbersService.findIdentityByPhone(
        candidate,
      );
      if (viaTable) return viaTable;
      const legacy = await this.unifiedIdentityRepo.findOne({
        where: { phone_number: candidate },
      });
      if (legacy) return legacy;
    }
    return null;
  }

  /**
   * Ensure phone is attached to identity in identity_phone_numbers.
   * @param manager - Optional. Pass when inside a transaction so the identity lookup sees uncommitted rows.
   */
  private async ensurePhoneAttached(
    identityId: string,
    rawPhone: string,
    manager?: EntityManager,
  ): Promise<void> {
    try {
      await this.identityPhoneNumbersService.attachPhoneNumberToIdentity(
        identityId,
        rawPhone,
        { isVerified: true },
        manager,
      );
    } catch (e: any) {
      if (e?.code === '23505' || e?.message?.includes('already linked')) {
        return;
      }
      throw e;
    }
  }

  /**
   * Get unified profile by phone. Returns null if no identity and no users.
   */
  async getProfileByPhone(
    phoneNumber: string,
  ): Promise<UnifiedProfileResult | null> {
    const identity = await this.findIdentityByPhoneOrLegacy(phoneNumber);
    if (identity) {
      const ivStatus = (
        identity.identity_verification_status ?? identity.kyc_status ?? 'PENDING'
      ).toUpperCase();
      const kycStatus =
        ivStatus === 'APPROVED'
          ? 'VERIFIED'
          : ivStatus === 'REJECTED'
            ? 'REJECTED'
            : identity.kyc_status ?? 'PENDING';
      const phone =
        identity.phone_number ??
        (await this.identityPhoneNumbersService.getPrimaryPhone(identity.id)) ??
        phoneNumber;
      return {
        id: identity.id,
        phone_number: phone,
        full_name: identity.full_name ?? null,
        email: identity.email ?? null,
        date_of_birth: identity.date_of_birth
          ? (identity.date_of_birth instanceof Date
              ? identity.date_of_birth.toISOString().slice(0, 10)
              : String(identity.date_of_birth).slice(0, 10))
          : null,
        city: identity.city ?? null,
        address: identity.address ?? null,
        kyc_status: kycStatus,
        identity_verified: identity.identity_verified ?? ivStatus === 'APPROVED',
        linked_services: Array.isArray(identity.linked_services)
          ? identity.linked_services
          : [],
      };
    }
    return null;
  }

  /**
   * Link all users with this phone to the unified identity and refresh linked_services (idempotent).
   */
  private async linkUsersToIdentity(
    phoneNumber: string,
    identityId: string,
  ): Promise<void> {
    const candidates = phoneLookupCandidates(phoneNumber);
    if (candidates.length === 0) return;
    await this.userRepository
      .createQueryBuilder()
      .update(User)
      .set({ unified_identity_id: identityId })
      .where('phone_number IN (:...candidates)', { candidates })
      .andWhere('unified_identity_id IS NULL')
      .execute();

    const users = await this.userRepository
      .createQueryBuilder('u')
      .select(['u.account_type'])
      .where('u.unified_identity_id = :id', { id: identityId })
      .getMany();
    const linkedServices = Array.from(
      new Set(users.map((u) => String(u.account_type ?? 'CONSUMER'))),
    );
    await this.unifiedIdentityRepo.update(identityId, {
      linked_services: linkedServices,
      updated_at: new Date(),
    });
  }

  /**
   * Update identity verification status on unified identity (call when ReusableIdentityVerification is synced).
   * Keeps getNexaProfileByPhone consistent with reusable KYC state.
   * @param identityVerified - true when APPROVED/VERIFIED
   * @param kycStatus - legacy: PENDING, APPROVED, VERIFIED, REJECTED
   */
  async updateKycStatus(
    unifiedIdentityId: string,
    identityVerified: boolean,
    kycStatus: string,
  ): Promise<void> {
    const identityStatus =
      identityVerified && ['APPROVED', 'VERIFIED'].includes((kycStatus ?? '').toUpperCase())
        ? 'APPROVED'
        : (kycStatus ?? 'PENDING').toUpperCase() === 'REJECTED'
          ? 'REJECTED'
          : 'PENDING';
    await this.unifiedIdentityRepo.update(unifiedIdentityId, {
      identity_verified: identityVerified,
      kyc_status: kycStatus,
      identity_verification_status: identityStatus,
      updated_at: new Date(),
    });
  }

  /**
   * Find unified identity by phone (read-only). Returns null if not found.
   * Uses identity_phone_numbers first, then legacy phone_number.
   */
  async findByPhone(phoneNumber: string): Promise<UnifiedIdentity | null> {
    return this.findIdentityByPhoneOrLegacy(phoneNumber);
  }

  /**
   * Find unified identity by id (read-only). Returns null if not found.
   */
  async findById(id: string): Promise<UnifiedIdentity | null> {
    return this.unifiedIdentityRepo.findOne({ where: { id } });
  }

  /**
   * Refresh linked_services on an identity from its attached users.
   */
  async refreshLinkedServices(identityId: string): Promise<void> {
    const users = await this.userRepository.find({
      where: { unified_identity_id: identityId },
      select: ['account_type'],
    });
    const linkedServices = Array.from(
      new Set(users.map((u) => String(u.account_type ?? 'CONSUMER'))),
    );
    await this.unifiedIdentityRepo.update(identityId, {
      linked_services: linkedServices,
      updated_at: new Date(),
    });
  }
}

